    {
      "cell_type": "markdown",
      "metadata": {
        "id": "925eeae6"
      },
      "source": [
        "### 2. Import Libraries and Load PDF Documents\n",
        "\n",
        "We import the required libraries for document loading, text splitting, embeddings, and the RAG framework. Then, we define a function to load PDF documents from a specified folder. In this case, we'll load the `Machine Learning with Python Cookbook (en).pdf` file, which was previously uploaded to the Colab environment."
      ]
    },
    {
      "cell_type": "code",
      "metadata": {
        "colab": {
          "base_uri": "https://localhost:8080/"
        },
        "id": "d87de1be",
        "outputId": "2662076a-b89e-4fe5-951c-9b32eb215d51"
      },
      "source": [
        "import os\n",
        "from langchain_community.document_loaders import PyPDFLoader\n",
        "from langchain_text_splitters import RecursiveCharacterTextSplitter\n",
        "from langchain_community.embeddings import HuggingFaceEmbeddings\n",
        "from transformers import pipeline\n",
        "from langchain_chroma import Chroma\n",
        "\n",
        "# Function to load PDF documents from a specified folder\n",
        "def load_docs(folder_path):\n",
        "    docs = []\n",
        "    for file in os.listdir(folder_path):\n",
        "        if file.endswith(\".pdf\"):\n",
        "            loader = PyPDFLoader(os.path.join(folder_path, file))\n",
        "            docs.extend(loader.load())\n",
        "    return docs\n",
        "\n",
        "# Specify the folder where your PDFs are stored (e.g., '/content' for Colab uploads)\n",
        "docs = load_docs(\"/content\")\n",
        "print(f\"PDF Pages Loaded: {len(docs)}\")"
      ],
      "execution_count": 6,
      "outputs": [
        {
          "output_type": "stream",
          "name": "stdout",
          "text": [
            "PDF Pages Loaded: 427\n"
          ]
        }
      ]
    },
    {
      "cell_type": "markdown",
      "metadata": {
        "id": "3d6832b4"
      },
      "source": [
        "### 3. Split Documents into Chunks\n",
        "\n",
        "To effectively process large documents and retrieve relevant information, we split the loaded PDF pages into smaller, manageable chunks. We use `RecursiveCharacterTextSplitter` to ensure chunks are contextually coherent, with a defined `chunk_size` and `chunk_overlap`."
      ]
    },
    {
      "cell_type": "code",
      "metadata": {
        "colab": {
          "base_uri": "https://localhost:8080/"
        },
        "id": "aec75f05",
        "outputId": "dc15f71d-e09c-45f3-fa59-13a9eb904cf5"
      },
      "source": [
        "# Initialize the text splitter with a chunk size of 500 characters and an overlap of 80 characters\n",
        "text_splitter = RecursiveCharacterTextSplitter(\n",
        "    chunk_size=500,\n",
        "    chunk_overlap=80\n",
        ")\n",
        "\n",
        "# Split the documents into chunks\n",
        "chunks = text_splitter.split_documents(docs)\n",
        "print(f\"Chunks Created: {len(chunks)}\")"
      ],
      "execution_count": 7,
      "outputs": [
        {
          "output_type": "stream",
          "name": "stdout",
          "text": [
            "Chunks Created: 1398\n"
          ]
        }
      ]
    },
    {
      "cell_type": "markdown",
      "metadata": {
        "id": "663b59f0"
      },
      "source": [
        "### 4. Create Embeddings and Vector Database\n",
        "\n",
        "We convert the text chunks into numerical vector representations (embeddings) using a pre-trained `HuggingFaceEmbeddings` model (`all-MiniLM-L6-v2`). These embeddings are then stored in a `Chroma` vector database, which allows for efficient similarity search to retrieve relevant chunks."
      ]
    },
